INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65017576', 65017576, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior  Penyusunan Konten Komunikasi  dan Publikasi Multikanal  Manajemen Risiko  Pembangunan Nasional (MRPN)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 80300000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '00', 'Lingkup kegiatan dan tanggung jawab untuk Jasa Konsultan Junior Penyusunan Konten Komunikasi dan Publikasi Multikanal Manajemen Risiko Pembangunan Nasional (MRPN) adalah sebagai berikut: Merumuskan strategi komunikasi tertulis untuk media cetak dan digital. Mengembangkan konsep, perencanaan, dan pengelolaan narasi konten media sosial yang bersifat informatif dan persuasif. Mengembangkan materi dan pesan komunikasi publik untuk laman (landing page) dan website instansi guna meningkatkan keterbacaan, pemahaman, dan aksesibilitas informasi publik Merancang naskah komunikasi kehumasan untuk berbagai media dan kegiatan meliputi video, brosur, siaran pers (press release), serta materi konferensi pers, dalam rangka mendukung konsistensi pesan, citra, dan reputasi instansi.', 'Pengembangan media komunikasi dan publikasi yang memuat uraian rencana konten media, penyusunan konten media, publikasi konten media yang dituangkan dalam Laporan Penyusunan Konten Komunikasi dan Publikasi Multikanal Manajemen Risiko Pembangunan Nasional (MRPN) sebagai bentuk pertanggungjawaban pelaksanaan kegiatan sekaligus sebagai rujukan dalam pengembangan media komunikasi dan publikasi di masa mendatang. Sehubungan dengan pelaksanaan kegiatan tersebut, penyampaian keluaran Jasa Konsultan Junior Penyusunan Konten Komunikasi dan Publikasi Multikanal Manajemen Risiko Pembangunan Nasional (MRPN) dilakukan secara bertahap dan dituangkan dalam laporan per termin. Sebagai berikut rinciannya: No Periode Keluaran per Termin 1 Termin 1 Laporan strategi komunikasi tertulis instansi untuk media cetak dan digital 2 Termin 2 Laporan Paket konten media sosial terencana (narasi, kalender konten, dan pesan utama) yang bersifat informatif dan persuasif Tahap 1 3 Termin 3 Laporan Naskah dan materi komunikasi publik untuk laman (landing page) dan website instansi. 4 Termin 4 Laporan Paket konten media sosial terencana (narasi, kalender konten, dan pesan utama) yang bersifat informatif dan persuasif Tahap 2 5 Termin 5 Laporan pedoman narasi dan pesan kunci komunikasi publik sebagai acuan konsistensi pesan dan reputasi instansi pada berbagai media dan kegiatan 6 Termin 6 Laporan Penyusunan Konten Komunikasi dan Publikasi Multikanal Manajemen Risiko Pembangunan Nasional (MRPN)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 332030);
