INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65017580', 65017580, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Perancangan Visual Publikasi dan Dokumentasi Aset Desain Grafis Komunikasi Manajemen Risiko Pembangunan Nasional (MRPN)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 71500000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Lingkup kegiatan dan tanggung jawab untuk Jasa Konsultan Junior Perancangan Visual Publikasi dan Dokumentasi Aset Desain Grafis Komunikasi Manajemen Risiko Pembangunan Nasional (MRPN) adalah untuk memberikan dukungan teknis yang bersifat profesional dan spesialis dalam pengembangan materi visual program, terutama untuk kebutuhan strategis yang memerlukan keahlian khusus yang fokus pada penguatan kualitas komunikasi visual guna mendukung pencapaian tujuan kegiatan.', 'Pengembangan media komunikasi dan publikasi yang memuat uraian mendesain materi visual seperti infografis, ilustrasi, layout dokumen non-formal, banner digital, dan elemen grafis lainnya yang dituangkan dalam Laporan Perancangan Visual Publikasi dan Dokumentasi Aset Desain Grafis Komunikasi Manajemen Risiko Pembangunan Nasional (MRPN) sebagai bentuk pertanggungjawaban pelaksanaan kegiatan sekaligus sebagai rujukan dalam pengembangan media komunikasi dan publikasi di masa mendatang. Sehubungan dengan pelaksanaan kegiatan tersebut, penyampaian keluaran Jasa Konsultan Junior Perancangan Visual Publikasi dan Dokumentasi Aset Desain Grafis Komunikasi Manajemen Risiko Pembangunan Nasional (MRPN) dilakukan secara bertahap dan dituangkan dalam laporan per termin. Sebagai berikut rinciannya: No Periode Keluaran per Termin 1 Termin 1 Laporan analisis kebutuhan media grafis instansi. 2 Termin 2 Laporan konsep dan kerangka desain grafis komunikasi publik. 3 Termin 3 Laporan Paket pengembangan elemen grafis komunikasi publik (ikonografi, tipografi, sistem tata letak). 4 Termin 4 Laporan standar dan pedoman identitas visual instansi 5 Termin 5 Laporan evaluasi efektivitas desain grafis 6 Termin 6 Laporan Perancangan Visual Publikasi dan Dokumentasi Aset Desain Grafis Komunikasi Manajemen Risiko Pembangunan Nasional (MRPN)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 337725);
