INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62937658', 62937658, 'analyze_legacy', 'Kementerian Sekretariat Negara', 'central', 'SEKRETARIAT KEMENTERIAN SEKRETARIAT NEGARA', 'Pengadaan Jasa Perawatan Aplikasi Kementerian Sekretariat Negara', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 71785000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 paket', 'Untuk memenuhi kebutuhan tersebut di atas, serta mengingat keterbatasan jumlah pegawai yang memiliki kompetensi dalam bidang pembangunan dan pengembangan aplikasi di lingkungan Pusat Pengembangan dan Layanan Sistem Informasi, maka diperlukan tenaga ahli profesional yang memiliki kompetensi dalam bidang pengembangan yang bersifat minor sampai dengan menengah yang dilakukan secara kolaborasi/swakelola dalam hal pembangunan, pengembangan, dan membantu dalam memelihara aplikasi sistem informasi di lingkungan Kementerian Sekretariat Negara serta dapat memberikan masukan dan saran terkait pengembangan maupun pembangunan sistem aplikasi di Kementerian Sekretariat Negara.', 'Ruang lingkup kegiatan pengadaan Jasa Perawatan Aplikasi Kementerian Sekretariat Negara ini terdiri atas: a. Melakukan pembangunan aplikasi berkolaborasi dengan pegawai pada Pusat Pengembangan dan Layanan Sistem Informasi yang bersifat swakelola sesuai dengan arahan pimpinan dan kebutuhan pengguna: 1) Melakukan identifikasi dan analisis desain kebutuhan aplikasi sesuai dengan kebutuhan; 2) Penyusunan dan pembuatan aplikasi; 3) Ujicoba, pengecekan error/malfungsi dan perbaikan; 4) Melakukan perbaikan dari hasil penetration test; 5) Deployment aplikasi; 6) Dokumentasi pembangunan aplikasi, spesifikasi teknis, pengujian fungsi, uji keamanan, manual penggunaan modul. b. Membuat penambahan modul yang bersifat minor sampai mengah pada aplikasi yang sudah ada sesuai dengan kebutuhan pengguna: 1) Melakukan identifikasi dan analisis desain kebutuhan modul baru pada aplikasi di lingkungan Kementerian Sekretariat Negara yang bersifat minor; 2) Penyusunan dan pembuatan modul; 3) Ujicoba, pengecekan error/malfungsi dan perbaikan modul; 4) Melakukan perbaikan dari hasil penetration test; 5) Deployment modul; 6) Dokumentasi database, spesifikasi teknis, pengujian fungsi, uji keamanan, manual penggunaan modul. c. Melakukan perbaikan modul pada aplikasi yang sudah ada sesuai dengan kebutuhan pengguna: 1) Melakukan identifikasi dan analisis kebutuhan modul yang diperbaiki pada aplikasi dil ingkungan Kementerian Sekretariat Negara; 2) Melakukan perbaikan modul yang sesuai dengan kebutuhan; 3) Ujicoba, pengecekan error/malfungsi dan perbaikan modul; 4) Melakukan perbaikan dari hasil penetration test; 5) Deployment modul; 6) Melengkapi dokumentasi database, spesifikasi teknis, pengujian fungsi, uji keamanan, manual penggunaan modul. d. Melakukan pemutakhiran database aplikasi sesuai dengan kebutuhan: 1) Melakukan identifikasi dan analisis struktur database pada aplikasi di lingkungan Kementerian Sekretariat Negara; 2) Merancang kebutuhan penambahan atau perbaikan database; 3) Melakukan penambahan atau perbaikan database yang sesuai dengan kebutuhan; 4) Melaporkan hasil kegiatan secara berkala. e. Melakukan monitoring aplikasi di lingkungan Kementerian Sekretariat Negara agar berjalan dengan normal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 338263);
