INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62936463', 62936463, 'analyze_legacy', 'Kota Tasikmalaya', 'kabkota', 'Dinas Kepemudaan, Olah Raga, Kebudayaan dan Pariwisata', 'Belanja Jasa Tenaga Keamanan Disporabudpar', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Tasikmalaya (Kota)', 191084016, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Ruang lingkup tugas yang dilaksanakan penyedia adalah mempelajari dan melaksanakan dokumen pelaksanaan paket pengadaan dan menyediakan tenaga kerja dengan standar kualifikasi dan kriteria tenaga kerja sebagaimana dipersyaratkan.', 'Kualifikasi Teknis Penyedia Persyaratan kualifikasi teknis untuk Penyedia, meliputi: A. Peserta yang berbadan usaha harus memiliki perizinan berusaha di bidang Penyediaan Sumber Daya Manusia dan Manajemen Fungsi Sumber Daya Manusia; B. Memiliki pengalaman paling kurang 1 (satu) Pekerjaan Jasa Penyediaan Sumber Daya Manusia dan Manajemen Fungsi Sumber Daya Manusia dalam kurun waktu 1 (satu) tahun terakhir, baik di lingkungan pemerintah atau swasta termasuk pengalaman subkontrak; C. Untuk kualifikasi usaha kecil yang baru berdiri kurang dari 3 tahun harus mempunyai 1 pengalaman pada bidang yang sama; D. Tidak masuk dalam Daftar hitam, keikutsertaannya tidak menimbulkan pertentangan kepentingan pihak yang terkait, tidak dalam pengawasan pengadilan, tidak pailit, kegiatan usahanya tidak sedang dihentikan dan/atau yang bertindak untuk dan atas nama Badan Usaha tidak sedang dalam menjalani sanksi pidana. Standar kualifikasi dan kriteria Tenaga Kerja (jasa keamanan) sebagai berikut: 1. Pendidikan minimal Sekolah Menengah Umum (SMU) atau sederajat; 2. Sehat jasmani dan rohani;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 338267);
